		function checkEnd() {
		  if (window.completedCount === window.totalItems) {
		    setTimeout(() => {
		      // لو فيه slices تانية
		      if (window.currentSlice < window.totalSlices - 1) {
		        setTimeout(() => {
		          window.currentSlice++;
		          loadNextSlice();
		          // root.next_slice_btn.visible = true;
		        }, 500);
		      } else {
		        root.gotoAndStop("result");
		      }
		    }, 2000);
		  }
		}
		
